//! Raw FFI bindings to libghostty-vt.
//!
//! Generated by bindgen from the C headers of the release pinned in `tools.toml`. Nothing
//! here is written by hand; use the `lume-vt` crate for a safe interface.
//!
//! The library is not thread-safe: all calls on one terminal must come from one thread.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(clippy::all)]
#![allow(rustdoc::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
